pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(uint256 amount, address player) public {
        vm.assume(player != address(0));
        amount = bound(amount, 0, 1 ether);

        vm.deal(player, 1 ether);

        uint256 potBefore = c.pot();

        vm.prank(player);
        bool ok;
        try c.play{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 potAfter = c.pot();

        assertTrue(potAfter % 10 == 0);
    }
}
